package com.eventmanager.controller;
import com.eventmanager.util.DB; import com.eventmanager.model.User; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException; import java.sql.*;
@WebServlet("/purchase") public class PurchaseServlet extends HttpServlet { protected void doPost(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");if(u==null||!"ATTENDEE".equals(u.role)){res.sendError(403);return;}try{int eventId=Integer.parseInt(req.getParameter("eventId"));int ticketId=Integer.parseInt(req.getParameter("ticketId"));double amount=Double.parseDouble(req.getParameter("amount"));try(Connection c=DB.getConnection()){c.setAutoCommit(false);int regId;try(PreparedStatement p=c.prepareStatement("SELECT id FROM registrations WHERE event_id=? AND attendee_id=?",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,eventId);p.setInt(2,u.id);ResultSet r=p.executeQuery();if(r.next())regId=r.getInt(1);else{try(PreparedStatement q=c.prepareStatement("INSERT INTO registrations(event_id,attendee_id,ticket_id) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){q.setInt(1,eventId);q.setInt(2,u.id);q.setInt(3,ticketId);q.executeUpdate();ResultSet k=q.getGeneratedKeys();k.next();regId=k.getInt(1);}}}try(PreparedStatement p=c.prepareStatement("INSERT INTO purchases(registration_id,amount) VALUES(?,?)")){p.setInt(1,regId);p.setDouble(2,amount);p.executeUpdate();}c.commit();}res.sendRedirect("dashboard");}catch(Exception e){throw new ServletException(e);}}}
